printf("%p\n", &n);   /* 0x7ffd... — 주소 */

int a[3] = {10, 20, 30};
int *p = a;

printf("%p\n", (void*)p);       /* 0x1000 */
printf("%p\n", (void*)(p + 1)); /* 0x1004 — 4 증가 */

char s[3] = {'a','b','c'};
char *q = s;
printf("%p\n", (void*)(q + 1)); /* 1 증가 — char 는 1바이트 */

#include <stdio.h>
#include <string.h>
int main(void) {
    char s[10] = "abc";
    printf("%zu %zu\n", sizeof(s), strlen(s));
    return 0;
}

void show(int arr[], int n) {   /* int *arr 과 완전히 같다 */
    printf("%zu\n", sizeof(arr));   /* 8 — 배열 크기가 아니다! */
    for (int i = 0; i < n; i++) printf("%d ", arr[i]);
    printf("\n");
}

int main(void) {
    int a[5] = {1,2,3,4,5};
    printf("%zu\n", sizeof(a));   /* 20 */
    show(a, 5);                   /* 크기를 따로 넘겨야 한다 */
    return 0;
}

void doubleAll(int *arr, int n) {
    for (int i = 0; i < n; i++) arr[i] *= 2;
}

int a[3] = {1,2,3};
doubleAll(a, 3);
printf("%d %d %d\n", a[0], a[1], a[2]);   /* 2 4 6 */

int m[2][3] = {{1,2,3}, {4,5,6}};

for (int i = 0; i < 2; i++) {
    for (int j = 0; j < 3; j++) printf("%d ", m[i][j]);
    printf("\n");
}
/* 메모리에는 1 2 3 4 5 6 순서로 나란히 놓인다 */

void f(int a[]) { a[0] = 99; }

int main(void) {
    int x[3] = {1,2,3};
    f(x);
    printf("%d\n", x[0]);
    return 0;
}

